-- NCLEX content rewrite, 2026-10-30. Ryan approved. 13 QuestionBankItem ids only.
-- Citation URLs from items.json source go in "references" (label + url).
-- The source column stays ai-curated/polished so the curated serve pool still includes the row.
-- Select-all correctAnswer is the keyed option texts joined with |||, in option order.
-- Single-best correctAnswer is the option text. itemType vignette / kind mcq matches other NCLEX MCQs.
-- contentHash is sha256(fieldId|subjectId|scenario|stem), lowercased and trimmed, same as the seed sync.
-- manual_correction is set so a later seed match cannot overwrite the rewrite.
-- Stale distractorRationale, clinicalReasoning, keyTakeaways, and expert/visual rationale are removed
-- because they still teach the previous key.

DO $guard$
BEGIN
  IF to_regclass('public.qbi_nclex_fixes13_20261030_backup') IS NULL THEN
    RAISE EXCEPTION 'backup table is missing; run 01-backup.sql first';
  END IF;
  IF (SELECT count(*) FROM qbi_nclex_fixes13_20261030_backup) <> 13 THEN
    RAISE EXCEPTION 'backup table does not hold 13 rows';
  END IF;
  IF (
    SELECT count(*)
    FROM "QuestionBankItem"
    WHERE id IN ('cmrmu08cb00fx1y3jc9rsnelz', 'cmroe7xjf00061ybznd77tf3j', 'cmr8ufrug009r1y0yy7zwc3fz', 'cmr74f8qx004b1ywujjp4k4ak', 'cmra5zpf600231ylwahnk5q4e', 'cmr7e70og002j1y9txjux05cj', 'cmqwues7900001y1sda6lynv6', 'cmr7gipdt00b41y59f9fm1kfb', 'cmr0xdqyg00071ybsvb4sqisw', 'cmrlxlbxn00041yci85r3kb95', 'cmqx0b7wx000h1y1klag1mky3', 'cmr0ufrka00251y7owlq2oh3d', 'cmr0pfqyf004q1yhdgfkg2m1u')
      AND "fieldId" = 'nursing'
  ) <> 13 THEN
    RAISE EXCEPTION 'expected exactly 13 nursing rows';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM (VALUES
  ($nclexfixes13$cmrmu08cb00fx1y3jc9rsnelz$nclexfixes13$::text, $nclexfixes13$A 30-year-old client comes to the clinic for a routine visit. She has smoked half a pack a day for 8 years (4 pack-years). Her last cervical screening, 4 years ago, was cytology alone with no HPV testing, and it was normal. Her mother was diagnosed with breast cancer at age 62. She has no symptoms.$nclexfixes13$::text, $nclexfixes13$Which screenings or services are indicated for this client at this visit? Select all that apply.$nclexfixes13$::text, $nclexfixes13$Cervical cytology test|||Blood pressure measurement|||Tobacco cessation counseling$nclexfixes13$::text, $nclexfixes13$USPSTF: cytology every 3 years at 21-29 and cytology every 3 years (or hrHPV/cotest every 5) at 30-65; her last test was 4 years ago, so she is due. Tobacco counseling and BP screening are routine adult preventive services. Mother diagnosed at 62 is not a high-risk pattern, so mammography is not started at 30; colonoscopy starts at 45 and bone density at 65. Low-dose CT lung screening is for ages 50-80 with 20 or more pack-years.$nclexfixes13$::text, 2::smallint, $nclexfixes13$select_all$nclexfixes13$::text, $nclexfixes13$select_all$nclexfixes13$::text, $nclexfixes13$["Low-dose chest CT scan","Cervical cytology test","Screening mammogram","Blood pressure measurement","BRCA gene testing","Tobacco cessation counseling"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"USPSTF cervical cancer screening","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/cervical-cancer-screening"}]$nclexfixes13$::jsonb, $nclexfixes13$ae0674fd0fca08d9218f8db4cb25709d433dcdb85ca3ceddd0a7b154adc6dda3$nclexfixes13$::text),
  ($nclexfixes13$cmroe7xjf00061ybznd77tf3j$nclexfixes13$::text, $nclexfixes13$A client who gave birth vaginally 2 hours ago reports feeling dizzy. The fundus is boggy and 2 cm above the umbilicus, and a perineal pad was saturated in 15 minutes. BP is 88/50 mm Hg (90 minutes ago: 118/72) and HR is 118/min. One 20-gauge IV of lactated Ringer's is infusing. The nurse begins fundal massage while another nurse calls the provider and the rapid response team.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take next?$nclexfixes13$::text, $nclexfixes13$Insert a second IV with a large-bore catheter$nclexfixes13$::text, $nclexfixes13$ACOG PB 183: hemorrhage with signs of hypovolemia (BP 88/50, HR 118) needs a team response and volume resuscitation; with only one 20-gauge line, large-bore access comes next. Quantifying blood loss matters but does not treat shock. Walking to void risks syncope, and waiting 15 minutes delays care.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Help the client to the bathroom to void","Insert a second IV with a large-bore catheter","Weigh the perineal pads to measure blood loss","Recheck the fundus and vitals in 15 minutes"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ACOG Practice Bulletin 183, postpartum hemorrhage","url":"https://www.acog.org/clinical/clinical-guidance/practice-bulletin/articles/2017/10/postpartum-hemorrhage"}]$nclexfixes13$::jsonb, $nclexfixes13$d327050b3872a321a868e9d82b2f15cfa740b6833c987854931047885d3bbbba$nclexfixes13$::text),
  ($nclexfixes13$cmr8ufrug009r1y0yy7zwc3fz$nclexfixes13$::text, $nclexfixes13$A 65-year-old client with atrial fibrillation for 3 months is scheduled for elective electrical cardioversion this morning. He takes warfarin 5 mg daily. Weekly INRs for the past 2 weeks were 2.4 and 2.2. Today's INR, drawn 1 hour ago and run by the hospital lab on a properly filled tube, is 1.8. No transesophageal echocardiogram is ordered. He has no bleeding or bruising.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take?$nclexfixes13$::text, $nclexfixes13$Notify the provider of the INR before the procedure$nclexfixes13$::text, $nclexfixes13$2023 ACC/AHA/ACCP/HRS AF guideline: AF over 48 hours needs at least 3 weeks of therapeutic anticoagulation (INR 2-3) or imaging to exclude thrombus before cardioversion. An INR of 1.8 is subtherapeutic, so the provider must decide (delay, TEE, dose change). Holding warfarin or giving vitamin K lowers anticoagulation further and raises stroke risk.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Request a repeat INR before the procedure","Continue preparing the client since INR is near goal","Give the scheduled warfarin dose before transfer","Notify the provider of the INR before the procedure"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"2023 ACC/AHA/ACCP/HRS atrial fibrillation guideline","url":"https://pubmed.ncbi.nlm.nih.gov/38033089/"}]$nclexfixes13$::jsonb, $nclexfixes13$1c4f2a2f3418576662d5c2fa8a3c3ec75f0e0c9f62f83a33c8d05d110e414008$nclexfixes13$::text),
  ($nclexfixes13$cmr74f8qx004b1ywujjp4k4ak$nclexfixes13$::text, $nclexfixes13$A 68-year-old client with type 2 diabetes receives insulin glargine and insulin lispro. The nurse finds the client diaphoretic. The client opens their eyes only to a loud voice, mumbles, and does not follow commands. Point-of-care glucose is 42 mg/dL. A saline lock is in place, and hypoglycemia treatment orders are active.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take first?$nclexfixes13$::text, $nclexfixes13$Give IV dextrose 50% as prescribed$nclexfixes13$::text, $nclexfixes13$ADA Standards of Care 2026, section 6: oral glucose is for a conscious client who can swallow; with altered mental status and unsafe swallow, glucose is given IV (or glucagon). Oral gel risks aspiration. Holding lispro or waiting for orders delays treatment of level 2-3 hypoglycemia.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Give IV dextrose 50% as prescribed","Give 15 g of glucose gel buccally","Give 4 oz of juice through a straw","Recheck glucose with a venous sample"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ADA Standards of Care, hypoglycemia","url":"https://pubmed.ncbi.nlm.nih.gov/41358894/"}]$nclexfixes13$::jsonb, $nclexfixes13$795611396ed6c2d4c0ff902627d4ba3b7536399e26c872b0247a1a2bc4a96593$nclexfixes13$::text),
  ($nclexfixes13$cmra5zpf600231ylwahnk5q4e$nclexfixes13$::text, $nclexfixes13$A 52-year-old client who lives in a homeless shelter is admitted with a 3-week cough, low-grade fevers, and a 4 kg weight loss. HIV status is unknown. The chest x-ray shows a right upper lobe infiltrate. Sputum smears for acid-fast bacilli (AFB) and a respiratory viral panel are ordered.$nclexfixes13$::text, $nclexfixes13$Which precautions should the nurse implement?$nclexfixes13$::text, $nclexfixes13$Airborne precautions with an N95 respirator$nclexfixes13$::text, $nclexfixes13$CDC isolation precautions, Appendix A: suspected pulmonary TB requires Airborne plus Standard precautions (AIIR and an N95 or higher respirator) until the likelihood of TB is negligible or 3 AFB smears are negative. Waiting for results is wrong. Droplet masks do not filter droplet nuclei, and contact precautions do not address the route.$nclexfixes13$::text, 4::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Droplet precautions with a surgical mask","Standard precautions until AFB results return","Airborne precautions with an N95 respirator","Contact precautions with gown and gloves"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"CDC isolation precautions, Appendix A","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/appendix-a-type-duration.html"}]$nclexfixes13$::jsonb, $nclexfixes13$aa751143cbd0966a86b5224b1269cf2badc7b247bfedd78bbbb8fdbfffe52236$nclexfixes13$::text),
  ($nclexfixes13$cmr7e70og002j1y9txjux05cj$nclexfixes13$::text, $nclexfixes13$A client at 39 weeks of gestation, in her first pregnancy, is admitted in labor. Cervix is 4 cm dilated, contractions are every 5 minutes, and the FHR is 140/min with moderate variability. She has been walking and changing positions. She says, "I'm scared because I don't know what is going to happen next."$nclexfixes13$::text, $nclexfixes13$Which response by the nurse best addresses the client's concern?$nclexfixes13$::text, $nclexfixes13$"Let me explain how labor usually goes from here on."$nclexfixes13$::text, $nclexfixes13$ACOG CO 766 supports continuous emotional support and low-intervention care in normal labor. Her stated concern is not knowing what comes next, so teaching about labor addresses it. She is already mobile, so more walking does not answer her worry; deferring to the provider and false reassurance block communication.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["\"Let me explain how labor usually goes from here on.\"","\"Walking more may help your labor move along faster.\"","\"It's common for first-time mothers to feel this way.\"","\"Your provider can explain that to you at your next exam.\""]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ACOG Committee Opinion 766, labor and birth","url":"https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2019/02/approaches-to-limit-intervention-during-labor-and-birth"}]$nclexfixes13$::jsonb, $nclexfixes13$8aa34eaa12dd51483aac363e4b1cfa0153d7e760b5603cedebf70633d6aa82af$nclexfixes13$::text),
  ($nclexfixes13$cmqwues7900001y1sda6lynv6$nclexfixes13$::text, $nclexfixes13$A 65-year-old client with dementia has been in bilateral soft wrist restraints for 2 hours for pulling at a central line. He received haloperidol 2 mg IM 1 hour ago. The nurse checks the client and the restraints.$nclexfixes13$::text, $nclexfixes13$Which finding should the nurse address first?$nclexfixes13$::text, $nclexfixes13$New difficulty arousing; SpO2 is 89%$nclexfixes13$::text, $nclexfixes13$42 CFR 482.13(f) requires monitoring of respiratory and circulatory status, skin integrity, and vital signs in restrained clients. A new decreased level of consciousness with SpO2 89% after an antipsychotic is an airway and breathing threat and comes first. Agitation, a 3-hour fluid gap, and blanching pink skin are lower priority.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Pulling against the wrist restraints","New difficulty arousing; SpO2 is 89%","Last oral intake of fluids 3 hours ago","Capillary refill of 2 seconds in left hand"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"42 CFR 482.13, restraint monitoring","url":"https://www.law.cornell.edu/cfr/text/42/482.13"}]$nclexfixes13$::jsonb, $nclexfixes13$91525766168b5b037e117b2d1f65f87270c919174665eea5eae6b40e5470d3c5$nclexfixes13$::text),
  ($nclexfixes13$cmr7gipdt00b41y59f9fm1kfb$nclexfixes13$::text, $nclexfixes13$A 35-year-old client who injects drugs is admitted with fever of 39.2 C (102.6 F), chills, and a new heart murmur. BP is 112/70 mm Hg and HR is 104/min. One culture set was drawn in the emergency department. Another set and IV vancomycin are prescribed.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take first?$nclexfixes13$::text, $nclexfixes13$Draw the remaining set of blood cultures$nclexfixes13$::text, $nclexfixes13$AHA scientific statement on infective endocarditis: at least 2-3 sets of blood cultures should be drawn before antibiotics, because antibiotics lower culture yield. The client is hemodynamically stable, so a short delay is safe. Fever and murmur do not require airborne precautions; echocardiography follows.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Hang the first dose of the IV vancomycin","Give the acetaminophen ordered for fever","Prepare the client for an echocardiogram","Draw the remaining set of blood cultures"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"AHA scientific statement, infective endocarditis","url":"https://pubmed.ncbi.nlm.nih.gov/26373316/"}]$nclexfixes13$::jsonb, $nclexfixes13$a8ee0599f8a476a5a49f71bee955721c412659464a2ead5c1fbd6c00f09f63c9$nclexfixes13$::text),
  ($nclexfixes13$cmr0xdqyg00071ybsvb4sqisw$nclexfixes13$::text, $nclexfixes13$A 45-year-old client with opioid use disorder takes methadone 80 mg orally each morning; the dose was confirmed with his treatment program. He is admitted with acute pancreatitis and rates his pain 9/10. RR is 18/min and he is alert. His methadone dose is due, and acetaminophen IV is the only analgesic ordered.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take?$nclexfixes13$::text, $nclexfixes13$Give methadone and request added pain medicine$nclexfixes13$::text, $nclexfixes13$CDC 2022 guideline warns against applying opioid limits to medications for opioid use disorder and against undertreating pain in people with substance use disorder. Methadone maintenance should continue (it treats OUD, not acute pain), and severe acute pain needs added analgesia from the provider. Holding methadone risks withdrawal; acetaminophen alone undertreats 9/10 pain.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Give acetaminophen and reassess pain in 1 hour","Hold the methadone dose to prevent oversedation","Give methadone and request added pain medicine","Split the methadone dose to cover the pain"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"CDC 2022 clinical practice guideline for prescribing opioids","url":"https://www.cdc.gov/mmwr/volumes/71/rr/rr7103a1.htm"}]$nclexfixes13$::jsonb, $nclexfixes13$c38cb6b50234fbda04c50fc4c62042582f9c41c3c795ffe3e1a9fb9fd4bf02b8$nclexfixes13$::text),
  ($nclexfixes13$cmrlxlbxn00041yci85r3kb95$nclexfixes13$::text, $nclexfixes13$A 60-year-old client with atrial fibrillation takes warfarin. She fell at home 6 hours ago and struck her head on a table. Her INR of 4.5 was reported to the provider on arrival, and warfarin is being held. She rated a headache 2/10 on arrival and now rates it 4/10. GCS is 15, BP is 150/88 mm Hg, and HR is 82/min.$nclexfixes13$::text, $nclexfixes13$Which new finding should the nurse report to the provider first?$nclexfixes13$::text, $nclexfixes13$Head pain that rose from 2/10 to 4/10$nclexfixes13$::text, $nclexfixes13$ACEP 2023 clinical policy (US): decision rules cannot be used to rule out head CT in a client with a minor head injury who takes an anticoagulant, and headache is a high-risk feature. NICE NG232 agrees: a head injury in a person on anticoagulants, and a persistent or worsening headache, are risk factors that call for urgent assessment and CT. A worsening headache after a head strike on warfarin may be an intracranial bleed and outranks the high INR, which is the risk factor rather than the injury.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Head pain that rose from 2/10 to 4/10","Bruises on both forearms and both shins","Pain and swelling in the right wrist","Blood pressure of 150/88 mm Hg at rest"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ACEP 2023 mild TBI clinical policy","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10617828/"},{"label":"NICE NG232 head injury","url":"https://www.nice.org.uk/guidance/ng232/chapter/Recommendations"}]$nclexfixes13$::jsonb, $nclexfixes13$4d951027ae3a24a1f66c1d3359aa2156cca495c0a6853e7fdcddde69e5de3706$nclexfixes13$::text),
  ($nclexfixes13$cmqx0b7wx000h1y1klag1mky3$nclexfixes13$::text, $nclexfixes13$A 55-year-old client with hypertension comes to the clinic for follow-up. BP is 150/95 mm Hg. He reports taking his medications as prescribed, and his food log shows he follows a 2 g sodium diet. He says he has felt more tired than usual, and the clinic scale shows a 2.3 kg (5 lb) weight gain since his visit 1 week ago.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take first?$nclexfixes13$::text, $nclexfixes13$Assess his lungs and check both legs for edema$nclexfixes13$::text, $nclexfixes13$2022 AHA/ACC/HFSA heart failure guideline: rapid weight gain with fatigue points to fluid retention, and congestion is assessed by lung sounds, edema, and other signs. Assessment comes before teaching. Diet review and exercise come later, and he already reports adherence.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Ask him to record his weight daily at home","Teach him to limit his fluids to 2 liters each day","Remind him to take his BP pills on time","Assess his lungs and check both legs for edema"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"2022 AHA/ACC/HFSA heart failure guideline","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]$nclexfixes13$::jsonb, $nclexfixes13$18bd1945112d57b3de852cc4ac6ea80dadfeb7211d7961fb7426eaa8b37c8b46$nclexfixes13$::text),
  ($nclexfixes13$cmr0ufrka00251y7owlq2oh3d$nclexfixes13$::text, $nclexfixes13$A 25-year-old client with no symptoms asks about her breast cancer risk. Her mother was diagnosed with breast cancer at age 42, and her maternal aunt had ovarian cancer at age 50. A familial risk assessment tool completed today is positive. Her clinical breast exam today is normal.$nclexfixes13$::text, $nclexfixes13$Which recommendation should the nurse expect the provider to make?$nclexfixes13$::text, $nclexfixes13$Refer to genetic counseling for review$nclexfixes13$::text, $nclexfixes13$USPSTF: women with a family history of breast or ovarian cancer should have a familial risk assessment, and those who screen positive should get genetic counseling and then testing if indicated. Testing comes after counseling, not before. Monthly self-exam is not a recommended screening method, and mammography is not started at 25 without an assessed high-risk plan.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Begin annual screening mammograms now","Refer to genetic counseling for review","Start tamoxifen to lower her cancer risk","Schedule a breast MRI before counseling"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"USPSTF BRCA-related cancer risk assessment","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/brca-related-cancer-risk-assessment-genetic-counseling-and-genetic-testing"}]$nclexfixes13$::jsonb, $nclexfixes13$ca220a379338bbf0d8bf3fc25f365c79ca8e013278deb89757f13cd6c79137dc$nclexfixes13$::text),
  ($nclexfixes13$cmr0pfqyf004q1yhdgfkg2m1u$nclexfixes13$::text, $nclexfixes13$A 55-year-old client in diabetic ketoacidosis has received IV insulin at 0.1 unit/kg/h and 0.9% sodium chloride for 6 hours. Glucose is now 240 mg/dL (520 on admission). Potassium is 5.6 mEq/L, the anion gap is 20, and pH is 7.21. BP is 118/72 mm Hg and urine output is 60 mL/h.$nclexfixes13$::text, $nclexfixes13$Which prescription should the nurse anticipate next?$nclexfixes13$::text, $nclexfixes13$Add dextrose to the IV and keep insulin on$nclexfixes13$::text, $nclexfixes13$2024 ADA/EASD hyperglycemic crises consensus: when glucose falls below about 250 mg/dL, dextrose is added and the insulin infusion continues until ketoacidosis resolves; the gap of 20 and pH 7.21 show it has not. Potassium is not added when K is above 5.0. BP and urine output show perfusion is adequate, so a bolus is not needed.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Stop the insulin and give SC insulin now","Add 20 mEq/L of KCl to each liter of IV fluid","Add dextrose to the IV and keep insulin on","Give a 1 L bolus of 0.9% sodium chloride"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"2024 ADA/EASD hyperglycemic crises consensus","url":"https://pubmed.ncbi.nlm.nih.gov/39052901/"}]$nclexfixes13$::jsonb, $nclexfixes13$fee1794fbefa33b5de100173da36aff458848945ba431733705ebc1b3ec6faeb$nclexfixes13$::text)
    ) AS v(id, scenario, question, correct_answer, explanation, difficulty, item_type, kind, options_json, refs, content_hash)
    JOIN "QuestionBankItem" AS q
      ON q."contentHash" = v.content_hash
     AND q.id <> v.id
  ) THEN
    RAISE EXCEPTION 'new contentHash collides with another row';
  END IF;
END
$guard$;

UPDATE "QuestionBankItem" AS q
SET
  scenario = v.scenario,
  question = v.question,
  "correctAnswer" = v.correct_answer,
  explanation = v.explanation,
  difficulty = v.difficulty,
  "itemType" = v.item_type,
  options = (
    (q.options::jsonb - 'distractorRationale' - 'clinicalReasoning' - 'keyTakeaways')
    || jsonb_build_object('options', v.options_json, 'kind', v.kind)
  )::text,
  "references" = v.refs,
  "generationMeta" = (
    COALESCE(q."generationMeta", '{}'::jsonb)
    - 'expertRationale'
    - 'expertRationaleVersion'
    - 'visualRationale'
    - 'rationaleEnrichedAt'
    - 'rationaleModel'
    - 'rationaleQualityScore'
    - 'rationaleEnrichFailCount'
    - 'rationaleEnrichFailReason'
  ) || jsonb_build_object('manualCorrection', true),
  "contentHash" = v.content_hash,
  manual_correction = true,
  active = true,
  "qaPassed" = true,
  "updatedAt" = NOW()
FROM (VALUES
  ($nclexfixes13$cmrmu08cb00fx1y3jc9rsnelz$nclexfixes13$::text, $nclexfixes13$A 30-year-old client comes to the clinic for a routine visit. She has smoked half a pack a day for 8 years (4 pack-years). Her last cervical screening, 4 years ago, was cytology alone with no HPV testing, and it was normal. Her mother was diagnosed with breast cancer at age 62. She has no symptoms.$nclexfixes13$::text, $nclexfixes13$Which screenings or services are indicated for this client at this visit? Select all that apply.$nclexfixes13$::text, $nclexfixes13$Cervical cytology test|||Blood pressure measurement|||Tobacco cessation counseling$nclexfixes13$::text, $nclexfixes13$USPSTF: cytology every 3 years at 21-29 and cytology every 3 years (or hrHPV/cotest every 5) at 30-65; her last test was 4 years ago, so she is due. Tobacco counseling and BP screening are routine adult preventive services. Mother diagnosed at 62 is not a high-risk pattern, so mammography is not started at 30; colonoscopy starts at 45 and bone density at 65. Low-dose CT lung screening is for ages 50-80 with 20 or more pack-years.$nclexfixes13$::text, 2::smallint, $nclexfixes13$select_all$nclexfixes13$::text, $nclexfixes13$select_all$nclexfixes13$::text, $nclexfixes13$["Low-dose chest CT scan","Cervical cytology test","Screening mammogram","Blood pressure measurement","BRCA gene testing","Tobacco cessation counseling"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"USPSTF cervical cancer screening","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/cervical-cancer-screening"}]$nclexfixes13$::jsonb, $nclexfixes13$ae0674fd0fca08d9218f8db4cb25709d433dcdb85ca3ceddd0a7b154adc6dda3$nclexfixes13$::text),
  ($nclexfixes13$cmroe7xjf00061ybznd77tf3j$nclexfixes13$::text, $nclexfixes13$A client who gave birth vaginally 2 hours ago reports feeling dizzy. The fundus is boggy and 2 cm above the umbilicus, and a perineal pad was saturated in 15 minutes. BP is 88/50 mm Hg (90 minutes ago: 118/72) and HR is 118/min. One 20-gauge IV of lactated Ringer's is infusing. The nurse begins fundal massage while another nurse calls the provider and the rapid response team.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take next?$nclexfixes13$::text, $nclexfixes13$Insert a second IV with a large-bore catheter$nclexfixes13$::text, $nclexfixes13$ACOG PB 183: hemorrhage with signs of hypovolemia (BP 88/50, HR 118) needs a team response and volume resuscitation; with only one 20-gauge line, large-bore access comes next. Quantifying blood loss matters but does not treat shock. Walking to void risks syncope, and waiting 15 minutes delays care.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Help the client to the bathroom to void","Insert a second IV with a large-bore catheter","Weigh the perineal pads to measure blood loss","Recheck the fundus and vitals in 15 minutes"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ACOG Practice Bulletin 183, postpartum hemorrhage","url":"https://www.acog.org/clinical/clinical-guidance/practice-bulletin/articles/2017/10/postpartum-hemorrhage"}]$nclexfixes13$::jsonb, $nclexfixes13$d327050b3872a321a868e9d82b2f15cfa740b6833c987854931047885d3bbbba$nclexfixes13$::text),
  ($nclexfixes13$cmr8ufrug009r1y0yy7zwc3fz$nclexfixes13$::text, $nclexfixes13$A 65-year-old client with atrial fibrillation for 3 months is scheduled for elective electrical cardioversion this morning. He takes warfarin 5 mg daily. Weekly INRs for the past 2 weeks were 2.4 and 2.2. Today's INR, drawn 1 hour ago and run by the hospital lab on a properly filled tube, is 1.8. No transesophageal echocardiogram is ordered. He has no bleeding or bruising.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take?$nclexfixes13$::text, $nclexfixes13$Notify the provider of the INR before the procedure$nclexfixes13$::text, $nclexfixes13$2023 ACC/AHA/ACCP/HRS AF guideline: AF over 48 hours needs at least 3 weeks of therapeutic anticoagulation (INR 2-3) or imaging to exclude thrombus before cardioversion. An INR of 1.8 is subtherapeutic, so the provider must decide (delay, TEE, dose change). Holding warfarin or giving vitamin K lowers anticoagulation further and raises stroke risk.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Request a repeat INR before the procedure","Continue preparing the client since INR is near goal","Give the scheduled warfarin dose before transfer","Notify the provider of the INR before the procedure"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"2023 ACC/AHA/ACCP/HRS atrial fibrillation guideline","url":"https://pubmed.ncbi.nlm.nih.gov/38033089/"}]$nclexfixes13$::jsonb, $nclexfixes13$1c4f2a2f3418576662d5c2fa8a3c3ec75f0e0c9f62f83a33c8d05d110e414008$nclexfixes13$::text),
  ($nclexfixes13$cmr74f8qx004b1ywujjp4k4ak$nclexfixes13$::text, $nclexfixes13$A 68-year-old client with type 2 diabetes receives insulin glargine and insulin lispro. The nurse finds the client diaphoretic. The client opens their eyes only to a loud voice, mumbles, and does not follow commands. Point-of-care glucose is 42 mg/dL. A saline lock is in place, and hypoglycemia treatment orders are active.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take first?$nclexfixes13$::text, $nclexfixes13$Give IV dextrose 50% as prescribed$nclexfixes13$::text, $nclexfixes13$ADA Standards of Care 2026, section 6: oral glucose is for a conscious client who can swallow; with altered mental status and unsafe swallow, glucose is given IV (or glucagon). Oral gel risks aspiration. Holding lispro or waiting for orders delays treatment of level 2-3 hypoglycemia.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Give IV dextrose 50% as prescribed","Give 15 g of glucose gel buccally","Give 4 oz of juice through a straw","Recheck glucose with a venous sample"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ADA Standards of Care, hypoglycemia","url":"https://pubmed.ncbi.nlm.nih.gov/41358894/"}]$nclexfixes13$::jsonb, $nclexfixes13$795611396ed6c2d4c0ff902627d4ba3b7536399e26c872b0247a1a2bc4a96593$nclexfixes13$::text),
  ($nclexfixes13$cmra5zpf600231ylwahnk5q4e$nclexfixes13$::text, $nclexfixes13$A 52-year-old client who lives in a homeless shelter is admitted with a 3-week cough, low-grade fevers, and a 4 kg weight loss. HIV status is unknown. The chest x-ray shows a right upper lobe infiltrate. Sputum smears for acid-fast bacilli (AFB) and a respiratory viral panel are ordered.$nclexfixes13$::text, $nclexfixes13$Which precautions should the nurse implement?$nclexfixes13$::text, $nclexfixes13$Airborne precautions with an N95 respirator$nclexfixes13$::text, $nclexfixes13$CDC isolation precautions, Appendix A: suspected pulmonary TB requires Airborne plus Standard precautions (AIIR and an N95 or higher respirator) until the likelihood of TB is negligible or 3 AFB smears are negative. Waiting for results is wrong. Droplet masks do not filter droplet nuclei, and contact precautions do not address the route.$nclexfixes13$::text, 4::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Droplet precautions with a surgical mask","Standard precautions until AFB results return","Airborne precautions with an N95 respirator","Contact precautions with gown and gloves"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"CDC isolation precautions, Appendix A","url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/appendix-a-type-duration.html"}]$nclexfixes13$::jsonb, $nclexfixes13$aa751143cbd0966a86b5224b1269cf2badc7b247bfedd78bbbb8fdbfffe52236$nclexfixes13$::text),
  ($nclexfixes13$cmr7e70og002j1y9txjux05cj$nclexfixes13$::text, $nclexfixes13$A client at 39 weeks of gestation, in her first pregnancy, is admitted in labor. Cervix is 4 cm dilated, contractions are every 5 minutes, and the FHR is 140/min with moderate variability. She has been walking and changing positions. She says, "I'm scared because I don't know what is going to happen next."$nclexfixes13$::text, $nclexfixes13$Which response by the nurse best addresses the client's concern?$nclexfixes13$::text, $nclexfixes13$"Let me explain how labor usually goes from here on."$nclexfixes13$::text, $nclexfixes13$ACOG CO 766 supports continuous emotional support and low-intervention care in normal labor. Her stated concern is not knowing what comes next, so teaching about labor addresses it. She is already mobile, so more walking does not answer her worry; deferring to the provider and false reassurance block communication.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["\"Let me explain how labor usually goes from here on.\"","\"Walking more may help your labor move along faster.\"","\"It's common for first-time mothers to feel this way.\"","\"Your provider can explain that to you at your next exam.\""]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ACOG Committee Opinion 766, labor and birth","url":"https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2019/02/approaches-to-limit-intervention-during-labor-and-birth"}]$nclexfixes13$::jsonb, $nclexfixes13$8aa34eaa12dd51483aac363e4b1cfa0153d7e760b5603cedebf70633d6aa82af$nclexfixes13$::text),
  ($nclexfixes13$cmqwues7900001y1sda6lynv6$nclexfixes13$::text, $nclexfixes13$A 65-year-old client with dementia has been in bilateral soft wrist restraints for 2 hours for pulling at a central line. He received haloperidol 2 mg IM 1 hour ago. The nurse checks the client and the restraints.$nclexfixes13$::text, $nclexfixes13$Which finding should the nurse address first?$nclexfixes13$::text, $nclexfixes13$New difficulty arousing; SpO2 is 89%$nclexfixes13$::text, $nclexfixes13$42 CFR 482.13(f) requires monitoring of respiratory and circulatory status, skin integrity, and vital signs in restrained clients. A new decreased level of consciousness with SpO2 89% after an antipsychotic is an airway and breathing threat and comes first. Agitation, a 3-hour fluid gap, and blanching pink skin are lower priority.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Pulling against the wrist restraints","New difficulty arousing; SpO2 is 89%","Last oral intake of fluids 3 hours ago","Capillary refill of 2 seconds in left hand"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"42 CFR 482.13, restraint monitoring","url":"https://www.law.cornell.edu/cfr/text/42/482.13"}]$nclexfixes13$::jsonb, $nclexfixes13$91525766168b5b037e117b2d1f65f87270c919174665eea5eae6b40e5470d3c5$nclexfixes13$::text),
  ($nclexfixes13$cmr7gipdt00b41y59f9fm1kfb$nclexfixes13$::text, $nclexfixes13$A 35-year-old client who injects drugs is admitted with fever of 39.2 C (102.6 F), chills, and a new heart murmur. BP is 112/70 mm Hg and HR is 104/min. One culture set was drawn in the emergency department. Another set and IV vancomycin are prescribed.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take first?$nclexfixes13$::text, $nclexfixes13$Draw the remaining set of blood cultures$nclexfixes13$::text, $nclexfixes13$AHA scientific statement on infective endocarditis: at least 2-3 sets of blood cultures should be drawn before antibiotics, because antibiotics lower culture yield. The client is hemodynamically stable, so a short delay is safe. Fever and murmur do not require airborne precautions; echocardiography follows.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Hang the first dose of the IV vancomycin","Give the acetaminophen ordered for fever","Prepare the client for an echocardiogram","Draw the remaining set of blood cultures"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"AHA scientific statement, infective endocarditis","url":"https://pubmed.ncbi.nlm.nih.gov/26373316/"}]$nclexfixes13$::jsonb, $nclexfixes13$a8ee0599f8a476a5a49f71bee955721c412659464a2ead5c1fbd6c00f09f63c9$nclexfixes13$::text),
  ($nclexfixes13$cmr0xdqyg00071ybsvb4sqisw$nclexfixes13$::text, $nclexfixes13$A 45-year-old client with opioid use disorder takes methadone 80 mg orally each morning; the dose was confirmed with his treatment program. He is admitted with acute pancreatitis and rates his pain 9/10. RR is 18/min and he is alert. His methadone dose is due, and acetaminophen IV is the only analgesic ordered.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take?$nclexfixes13$::text, $nclexfixes13$Give methadone and request added pain medicine$nclexfixes13$::text, $nclexfixes13$CDC 2022 guideline warns against applying opioid limits to medications for opioid use disorder and against undertreating pain in people with substance use disorder. Methadone maintenance should continue (it treats OUD, not acute pain), and severe acute pain needs added analgesia from the provider. Holding methadone risks withdrawal; acetaminophen alone undertreats 9/10 pain.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Give acetaminophen and reassess pain in 1 hour","Hold the methadone dose to prevent oversedation","Give methadone and request added pain medicine","Split the methadone dose to cover the pain"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"CDC 2022 clinical practice guideline for prescribing opioids","url":"https://www.cdc.gov/mmwr/volumes/71/rr/rr7103a1.htm"}]$nclexfixes13$::jsonb, $nclexfixes13$c38cb6b50234fbda04c50fc4c62042582f9c41c3c795ffe3e1a9fb9fd4bf02b8$nclexfixes13$::text),
  ($nclexfixes13$cmrlxlbxn00041yci85r3kb95$nclexfixes13$::text, $nclexfixes13$A 60-year-old client with atrial fibrillation takes warfarin. She fell at home 6 hours ago and struck her head on a table. Her INR of 4.5 was reported to the provider on arrival, and warfarin is being held. She rated a headache 2/10 on arrival and now rates it 4/10. GCS is 15, BP is 150/88 mm Hg, and HR is 82/min.$nclexfixes13$::text, $nclexfixes13$Which new finding should the nurse report to the provider first?$nclexfixes13$::text, $nclexfixes13$Head pain that rose from 2/10 to 4/10$nclexfixes13$::text, $nclexfixes13$ACEP 2023 clinical policy (US): decision rules cannot be used to rule out head CT in a client with a minor head injury who takes an anticoagulant, and headache is a high-risk feature. NICE NG232 agrees: a head injury in a person on anticoagulants, and a persistent or worsening headache, are risk factors that call for urgent assessment and CT. A worsening headache after a head strike on warfarin may be an intracranial bleed and outranks the high INR, which is the risk factor rather than the injury.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Head pain that rose from 2/10 to 4/10","Bruises on both forearms and both shins","Pain and swelling in the right wrist","Blood pressure of 150/88 mm Hg at rest"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"ACEP 2023 mild TBI clinical policy","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10617828/"},{"label":"NICE NG232 head injury","url":"https://www.nice.org.uk/guidance/ng232/chapter/Recommendations"}]$nclexfixes13$::jsonb, $nclexfixes13$4d951027ae3a24a1f66c1d3359aa2156cca495c0a6853e7fdcddde69e5de3706$nclexfixes13$::text),
  ($nclexfixes13$cmqx0b7wx000h1y1klag1mky3$nclexfixes13$::text, $nclexfixes13$A 55-year-old client with hypertension comes to the clinic for follow-up. BP is 150/95 mm Hg. He reports taking his medications as prescribed, and his food log shows he follows a 2 g sodium diet. He says he has felt more tired than usual, and the clinic scale shows a 2.3 kg (5 lb) weight gain since his visit 1 week ago.$nclexfixes13$::text, $nclexfixes13$Which action should the nurse take first?$nclexfixes13$::text, $nclexfixes13$Assess his lungs and check both legs for edema$nclexfixes13$::text, $nclexfixes13$2022 AHA/ACC/HFSA heart failure guideline: rapid weight gain with fatigue points to fluid retention, and congestion is assessed by lung sounds, edema, and other signs. Assessment comes before teaching. Diet review and exercise come later, and he already reports adherence.$nclexfixes13$::text, 2::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Ask him to record his weight daily at home","Teach him to limit his fluids to 2 liters each day","Remind him to take his BP pills on time","Assess his lungs and check both legs for edema"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"2022 AHA/ACC/HFSA heart failure guideline","url":"https://pubmed.ncbi.nlm.nih.gov/35363499/"}]$nclexfixes13$::jsonb, $nclexfixes13$18bd1945112d57b3de852cc4ac6ea80dadfeb7211d7961fb7426eaa8b37c8b46$nclexfixes13$::text),
  ($nclexfixes13$cmr0ufrka00251y7owlq2oh3d$nclexfixes13$::text, $nclexfixes13$A 25-year-old client with no symptoms asks about her breast cancer risk. Her mother was diagnosed with breast cancer at age 42, and her maternal aunt had ovarian cancer at age 50. A familial risk assessment tool completed today is positive. Her clinical breast exam today is normal.$nclexfixes13$::text, $nclexfixes13$Which recommendation should the nurse expect the provider to make?$nclexfixes13$::text, $nclexfixes13$Refer to genetic counseling for review$nclexfixes13$::text, $nclexfixes13$USPSTF: women with a family history of breast or ovarian cancer should have a familial risk assessment, and those who screen positive should get genetic counseling and then testing if indicated. Testing comes after counseling, not before. Monthly self-exam is not a recommended screening method, and mammography is not started at 25 without an assessed high-risk plan.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Begin annual screening mammograms now","Refer to genetic counseling for review","Start tamoxifen to lower her cancer risk","Schedule a breast MRI before counseling"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"USPSTF BRCA-related cancer risk assessment","url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/brca-related-cancer-risk-assessment-genetic-counseling-and-genetic-testing"}]$nclexfixes13$::jsonb, $nclexfixes13$ca220a379338bbf0d8bf3fc25f365c79ca8e013278deb89757f13cd6c79137dc$nclexfixes13$::text),
  ($nclexfixes13$cmr0pfqyf004q1yhdgfkg2m1u$nclexfixes13$::text, $nclexfixes13$A 55-year-old client in diabetic ketoacidosis has received IV insulin at 0.1 unit/kg/h and 0.9% sodium chloride for 6 hours. Glucose is now 240 mg/dL (520 on admission). Potassium is 5.6 mEq/L, the anion gap is 20, and pH is 7.21. BP is 118/72 mm Hg and urine output is 60 mL/h.$nclexfixes13$::text, $nclexfixes13$Which prescription should the nurse anticipate next?$nclexfixes13$::text, $nclexfixes13$Add dextrose to the IV and keep insulin on$nclexfixes13$::text, $nclexfixes13$2024 ADA/EASD hyperglycemic crises consensus: when glucose falls below about 250 mg/dL, dextrose is added and the insulin infusion continues until ketoacidosis resolves; the gap of 20 and pH 7.21 show it has not. Potassium is not added when K is above 5.0. BP and urine output show perfusion is adequate, so a bolus is not needed.$nclexfixes13$::text, 3::smallint, $nclexfixes13$vignette$nclexfixes13$::text, $nclexfixes13$mcq$nclexfixes13$::text, $nclexfixes13$["Stop the insulin and give SC insulin now","Add 20 mEq/L of KCl to each liter of IV fluid","Add dextrose to the IV and keep insulin on","Give a 1 L bolus of 0.9% sodium chloride"]$nclexfixes13$::jsonb, $nclexfixes13$[{"label":"2024 ADA/EASD hyperglycemic crises consensus","url":"https://pubmed.ncbi.nlm.nih.gov/39052901/"}]$nclexfixes13$::jsonb, $nclexfixes13$fee1794fbefa33b5de100173da36aff458848945ba431733705ebc1b3ec6faeb$nclexfixes13$::text)
) AS v(id, scenario, question, correct_answer, explanation, difficulty, item_type, kind, options_json, refs, content_hash)
WHERE q.id = v.id
  AND q."fieldId" = 'nursing';

DO $guard$
BEGIN
